CREATE EXCEPTION FIXTURE_FAILURE 'BotHost database assertion failed';
COMMIT;
CREATE VIEW FIXTURE_ALLOWED (HOST_ID, BOT_ID, USER_ID) AS
SELECT B.HOST_ID, B.OWNED_BOT_ID, U.BOT_USER_ID
FROM OWNED_BOT_TBL B CROSS JOIN BOT_USER_TBL U
WHERE B.ENABLED = 1 AND U.ENABLED = 1
AND EXISTS (SELECT 1 FROM BOT_GRANT_TBL G
            WHERE G.BOT_ID = B.OWNED_BOT_ID AND G.OPERATION_CODE = 'git.patch')
AND EXISTS (SELECT 1 FROM USER_BOT_GRANT_TBL G
            WHERE G.BOT_ID = B.OWNED_BOT_ID AND G.USER_ID = U.BOT_USER_ID
              AND G.OPERATION_CODE = 'git.patch');
COMMIT;
SET TERM ^ ;
EXECUTE BLOCK AS
DECLARE N INTEGER;
BEGIN
    SELECT COUNT(*) FROM RDB$RELATIONS
      WHERE COALESCE(RDB$SYSTEM_FLAG, 0) = 0 AND RDB$VIEW_BLR IS NULL INTO :N;
    IF (N <> 5) THEN EXCEPTION FIXTURE_FAILURE 'Expected exactly five tables';
    INSERT INTO BOT_HOST_TBL (HOST_KEY) VALUES ('fixture-host');
    INSERT INTO BOT_HOST_TBL (HOST_KEY) VALUES ('other-host');
    IF (NOT EXISTS(SELECT 1 FROM BOT_HOST_TBL WHERE BOT_HOST_ID = 1)) THEN
        EXCEPTION FIXTURE_FAILURE 'Generated primary key missing';
    INSERT INTO OWNED_BOT_TBL
      (HOST_ID, NAME, BARE_JID, ENABLED, ACTIVE, PROVIDER_STATE, XMPP_STATE, DIAGNOSTIC, UPDATED_AT)
      VALUES (1, 'owned', 'bot@example.invalid', 1, 1, 'ready', 'connected', 'O''Brien fixture', CURRENT_TIMESTAMP);
    INSERT INTO OWNED_BOT_TBL (HOST_ID, NAME, ENABLED) VALUES (1, 'other-bot', 1);
    INSERT INTO BOT_USER_TBL (BARE_JID, ENABLED) VALUES ('user@example.invalid', 1);
    IF (NOT EXISTS(SELECT 1 FROM OWNED_BOT_TBL WHERE OWNED_BOT_ID = 1
       AND ACTIVE = 1 AND PROVIDER_STATE = 'ready' AND XMPP_STATE = 'connected'
       AND DIAGNOSTIC = 'O''Brien fixture' AND UPDATED_AT IS NOT NULL)) THEN
        EXCEPTION FIXTURE_FAILURE 'Status round trip failed';
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'Missing grants must deny';
    INSERT INTO BOT_GRANT_TBL (BOT_ID, OPERATION_CODE) VALUES (1, 'git.patch');
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'Bot grant alone must deny';
    DELETE FROM BOT_GRANT_TBL;
    INSERT INTO USER_BOT_GRANT_TBL (USER_ID, BOT_ID, OPERATION_CODE) VALUES (1, 1, 'git.patch');
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'User grant alone must deny';
    INSERT INTO BOT_GRANT_TBL (BOT_ID, OPERATION_CODE) VALUES (1, 'git.patch');
    IF (NOT EXISTS(SELECT 1 FROM FIXTURE_ALLOWED WHERE HOST_ID = 1 AND BOT_ID = 1 AND USER_ID = 1)) THEN
        EXCEPTION FIXTURE_FAILURE 'Both grants must allow';
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED WHERE HOST_ID = 2)) THEN
        EXCEPTION FIXTURE_FAILURE 'Wrong host must deny';
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED WHERE BOT_ID = 2)) THEN
        EXCEPTION FIXTURE_FAILURE 'Wrong bot must deny';
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED WHERE USER_ID = 999)) THEN
        EXCEPTION FIXTURE_FAILURE 'Unknown user must deny';
    UPDATE OWNED_BOT_TBL SET ENABLED = 0 WHERE OWNED_BOT_ID = 1;
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'Disabled bot must deny';
    UPDATE OWNED_BOT_TBL SET ENABLED = 1 WHERE OWNED_BOT_ID = 1;
    UPDATE BOT_USER_TBL SET ENABLED = 0 WHERE BOT_USER_ID = 1;
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'Disabled user must deny';
    UPDATE BOT_USER_TBL SET ENABLED = 1 WHERE BOT_USER_ID = 1;
    INSERT INTO BOT_GRANT_TBL (BOT_ID, OPERATION_CODE) VALUES (1, 'git.patch');
    INSERT INTO USER_BOT_GRANT_TBL (USER_ID, BOT_ID, OPERATION_CODE) VALUES (1, 1, 'git.patch');
    SELECT COUNT(*) FROM FIXTURE_ALLOWED INTO :N;
    IF (N <> 1) THEN EXCEPTION FIXTURE_FAILURE 'Duplicate grants multiplied result';
    DELETE FROM USER_BOT_GRANT_TBL WHERE USER_ID = 1 AND BOT_ID = 1 AND OPERATION_CODE = 'git.patch';
    IF (EXISTS(SELECT 1 FROM FIXTURE_ALLOWED)) THEN
        EXCEPTION FIXTURE_FAILURE 'Revocation must remove all matching grants';
END^
SET TERM ; ^
COMMIT;
SELECT 'DATABASE_ASSERTIONS_PASSED' AS RESULT FROM RDB$DATABASE;
QUIT;
